<script setup>import{computed,onMounted,ref}from'vue';import{api}from'../../api/http.js';import PageHeader from'../../components/common/PageHeader.vue';const products=ref([]),cart=ref([]),payment=ref('Cash'),message=ref(''),error=ref('');const money=n=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD'}).format(n||0);const total=computed(()=>cart.value.reduce((s,x)=>s+x.price*x.quantity,0));async function load(){try{products.value=(await api.get('/workspace/pos')).products}catch(x){error.value=x.message}}function add(p){const x=cart.value.find(i=>i.id===p.id);if(x&&x.quantity<p.stock_quantity)x.quantity++;else if(!x)cart.value.push({...p,quantity:1})}async function checkout(){try{const d=await api.post('/workspace/pos/checkout',{items:cart.value.map(x=>({product_id:x.id,quantity:x.quantity})),payment_method:payment.value});message.value=`Order ${d.order_id} completed — ${money(d.total)}`;cart.value=[];await load()}catch(x){error.value=x.message}}onMounted(load)</script><template><PageHeader title="Point of Sale" description="Process sales with automatic stock and ledger updates."/><p v-if="error" class="form-error">{{error}}</p><p v-if="message" class="success-message">{{message}}</p><div class="pos-layout"><section><div class="product-grid"><button v-for="p in products" class="product-card" @click="add(p)"><strong>{{p.emoji}} {{p.name}}</strong><span>{{money(p.price)}}</span><small>{{p.stock_quantity}} in stock</small></button></div></section><aside class="cart-card"><h2>Current sale</h2><div v-for="i in cart" class="cart-line"><span>{{i.name}} × {{i.quantity}}</span><strong>{{money(i.price*i.quantity)}}</strong></div><p v-if="!cart.length">Cart is empty.</p><div class="cart-total"><span>Total</span><strong>{{money(total)}}</strong></div><select v-model="payment"><option>Cash</option><option>Card</option><option>QR</option></select><button class="primary-button" :disabled="!cart.length" @click="checkout">Complete sale</button></aside></div></template>